    assert_eq!(candidate("<A><B><![CDATA[<C></C>]]></B></A>"), True);
    assert_eq!(candidate("<OUTER><INNER><![CDATA[<INNER>CDATA</INNER>]]></INNER></OUTER>"), True);
    assert_eq!(candidate("<![CDATA[ignore <TAG> tags <INSIDE> </INSIDE> </TAG> ]]>"), True);
    assert_eq!(candidate("<A><B><C></C><D><![CDATA[TEXT]]></D></B></A>"), True);
    assert_eq!(candidate("<A><B><C></C><D></D></B></A>"), True);
    assert_eq!(candidate("<![CDATA[ignore <A><B><C></C></B></A> here]]><A></A>"), False);
    assert_eq!(candidate("<A><B><![CDATA[<C><D></D></C>]]></B><C><D><![CDATA[<E><F></F></E>]]></D></C></A>"), True);
    assert_eq!(candidate("<ALMOST><INNER><![CDATA[</INNER>]]></ALMOST>"), False);
    assert_eq!(candidate("<A><B><C><![CDATA[unmatched ]]></C></B></A>"), True);
    assert_eq!(candidate("<A><![CDATA[<B><![CDATA[wahaha>]]></A>"), True);
    assert_eq!(candidate("<X><Y><![CDATA[Not a tag>]]></Y></X>"), True);
    assert_eq!(candidate("<A><![CDATA[This is some text <B></B> with CDATA]]></A>"), True);
    assert_eq!(candidate("<A><B><C></C></B></A><D></D>"), False);
    assert_eq!(candidate("<A><B><![CDATA[<A></A>]]></B></A><C><D><![CDATA[<E></E>]]></D></C>"), False);
    assert_eq!(candidate("<A><B>content<![CDATA[<C>content</C>]]></B><![CDATA[content]]></A>"), True);
    assert_eq!(candidate("<A><![CDATA[<B>]]></A>"), True);
    assert_eq!(candidate("<A><![CDATA[<B><C><D><E><F><G><![CDATA[wahaha]]></G></F></E></D></C></B></A>></B>"), False);
    assert_eq!(candidate("<A><B><C><![CDATA[wahaha]]></C></D></B></A>"), False);
    assert_eq!(candidate("<A><B><![CDATA[<B></C>]]></B></A>"), True);
    assert_eq!(candidate("<A><B><C><D><E><F><G><![CDATA[wahaha]]></G>></F></E></D></C></B></A>"), True);
    assert_eq!(candidate("<A>content<![CDATA[<B>content</B>]]></A>"), True);
    assert_eq!(candidate("<A><B><C><D><E><F><G><![CDATA[wahaha>]]></F></E></D></C></B></A>"), False);
}
